import math

def expected_triangles(n: int, p: float) -> float:
    return math.comb(n, 3) * p ** 3

def expected_isolated(n: int, p: float) -> float:
    return n * (1.0 - p) ** (n - 1)

def main() -> None:
    for c in (0.5, 1.0, 2.0):
        print(f'c = {c}: limit c^3/6 = {c**3/6:.6f}')
        for n in (10, 100, 1000, 10000):
            print(f'  n={n:>6}  E[#triangles]={expected_triangles(n, c/n):.6f}')
    print('Scale separation (E[#isolated]):')
    for n in (100, 1000, 10000, 100000):
        giant = expected_isolated(n, 1.0 / n)
        conn = expected_isolated(n, math.log(n) / n)
        print(f'  n={n:>6}  p=1/n -> {giant:12.3f}   p=ln(n)/n -> {conn:.4f}')

if __name__ == '__main__':
    main()

