function FirstMoments(n, p):
    edges     <- C(n,2) * p
    triangles <- C(n,3) * p^3
    isolated  <- n * (1 - p)^(n - 1)
    return (edges, triangles, isolated)

function FirstMomentTriangleBound(n, p):
    mean <- C(n,3) * p^3            # E[#triangles]
    bound <- min(mean, 1)           # P(>=1 triangle) <= mean
    triangle_free_aas <- (n * p is small)
    return (bound, triangle_free_aas)

function SecondMomentZeroBound(mean, variance):
    require mean > 0
    return variance / mean^2        # P(X = 0) <= Var/E^2

